<?php
require __DIR__.'/config.php';$me=require_auth();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id||$id<1){http_response_code(404);exit('Transaction not found.');}$s=db()->prepare('SELECT t.transaction_id,t.reference_number,t.account_id,t.transaction_type,t.amount,t.balance_before,t.balance_after,t.related_account_id,t.description,t.status,t.created_at,a.account_number,a.account_title,a.currency FROM transactions t JOIN accounts a ON a.account_id=t.account_id JOIN account_holders h ON h.account_id=a.account_id WHERE h.customer_id=? AND t.transaction_id=?');$s->execute([$me['customer_id'],$id]);$t=$s->fetch();if(!$t){http_response_code(404);exit('Transaction not found.');}$related=null;if($t['related_account_id']){$s=db()->prepare('SELECT account_number FROM accounts WHERE account_id=?');$s->execute([$t['related_account_id']]);$related=$s->fetchColumn();}render_start('Transaction slip');?><section class="page-heading no-print"><div class="eyebrow dark">Transaction record</div><h1>Transaction slip</h1><p>Official account activity record for your reference.</p></section><article class="slip"><header class="slip-head"><div><div class="eyebrow dark">BankEase</div><h2>Transaction receipt</h2></div><span class="badge"><?=e(ucfirst($t['status']))?></span></header><div class="slip-amount"><span><?=e(ucwords(str_replace('_',' ',$t['transaction_type'])))?></span><strong><?=e($t['currency'])?> <?=e(number_format((float)$t['amount'],2))?></strong></div><dl><dt>Reference number</dt><dd><?=e($t['reference_number'])?></dd><dt>Date &amp; time</dt><dd><?=e($t['created_at'])?></dd><dt>Account title</dt><dd><?=e($t['account_title'])?></dd><dt>Account number</dt><dd><?=e($t['account_number'])?></dd><?php if($related):?><dt>Related BankEase account</dt><dd>•••• <?=e(substr($related,-4))?></dd><?php endif;?><?php if($t['description']):?><dt>Description</dt><dd><?=e($t['description'])?></dd><?php endif;?><dt>Balance before</dt><dd><?=e($t['currency'])?> <?=e(number_format((float)$t['balance_before'],2))?></dd><dt>Balance after</dt><dd><?=e($t['currency'])?> <?=e(number_format((float)$t['balance_after'],2))?></dd></dl><p class="slip-note">This receipt is generated from the BankEase transaction ledger.</p></article><div class="actions no-print"><button class="button navy" type="button" onclick="window.print()">Print slip</button><a class="button pale" href="<?=e(url('activity.php'))?>">Back to activity</a></div><?php render_end();?>
